Method.Implementation:

	#define ND(%directory) ##class(%File).NormalizeDirectory(%directory)
	$$$TRACE("Enter UnZip...")
	try {
		Set tSC=$$$OK
		Set tQuery=##class(%ResultSet).%New("%File:FileSet")
	    Set tSC= tQuery.Execute(..ZipFileDirectory,"*.zip",,0)
	    $$$TRACE("Loop Zip files...")
	    While tQuery.%Next() {
		   Set tFilename=tQuery.GetData(1)
		   $$$TRACE("Zip File: "_tFilename)
		   if ..checkFile(tFilename) {
		     set args=3
		     set args(1)=tFilename
		     set args(2)="-d"
		     set args(3)=..TargetDirectory
		     set cmd="unzip "_tFilename_" -d "_..TargetDirectory
		     $$$TRACE("TD: "_..TargetDirectory)
		     Set tStatus=$ZF(-100,"/SHELL", "unzip",.args) If tStatus Set tSC=$$$ERROR($$$GeneralError,"Unable to "_cmd) Quit
  	   	     $$$TRACE("Delete Zip File: "_tFilename)
		     Set tSC = ##class(%File).Delete(tFilename,.tsc) 	
		   }
		   else {
			   Set tSC=$$$ERROR($$$GeneralError,"Zip file access failed... ") Quit
		   }	   
	    }

} Catch ex {
		Set tSC = ex.AsStatus()
	}
	Quit tSC
